--
-- Columns the SQL export has to translate with care, in the form pg_dump 16 writes (written
-- by hand; the CI job "SQL on real servers" loads it into PostgreSQL 16 as it is).
--

SET statement_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET client_min_messages = warning;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: account; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.account (
    id bigint NOT NULL,
    email text NOT NULL,
    nick text DEFAULT ''::text NOT NULL,
    tags text[] DEFAULT ARRAY[]::text[],
    valid_until timestamp without time zone DEFAULT 'infinity'::timestamp without time zone,
    note character varying(40) DEFAULT '(none)'::character varying,
    code character varying(10) DEFAULT '007'::character varying,
    word character varying(10) DEFAULT 'NULL'::character varying,
    blank character varying(10) DEFAULT ' '::character varying,
    path character varying(40) DEFAULT 'C:\temp'::character varying,
    marker character varying(10) DEFAULT 'a::b'::character varying,
    gender character varying(6),
    status character varying(10) DEFAULT 'ACTIVE'::character varying NOT NULL,
    active boolean DEFAULT true NOT NULL,
    data jsonb DEFAULT '{}'::jsonb NOT NULL,
    uid uuid DEFAULT gen_random_uuid() NOT NULL,
    created_at timestamp(6) without time zone DEFAULT now() NOT NULL,
    born date DEFAULT CURRENT_DATE,
    "offset" integer,
    "window" integer,
    "user" text,
    "Rank" integer,
    CONSTRAINT account_gender_check CHECK (((gender)::text = ANY ((ARRAY['MALE'::character varying, 'FEMALE'::character varying])::text[]))),
    CONSTRAINT account_status_check CHECK (((status)::text = ANY ((ARRAY['ACTIVE'::character varying, 'NONE'::character varying, 'TRUE'::character varying])::text[]))),
    CONSTRAINT account_marker_check CHECK (((marker)::text <> 'x~y'::text))
);


ALTER TABLE public.account OWNER TO postgres;

--
-- Name: account_id_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

ALTER TABLE public.account ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.account_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: session; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.session (
    token text NOT NULL,
    account_id bigint NOT NULL,
    "order" integer DEFAULT 0 NOT NULL
);


ALTER TABLE public.session OWNER TO postgres;

--
-- Name: active_account; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.active_account AS
 SELECT id,
    email
   FROM public.account
  WHERE active;


ALTER VIEW public.active_account OWNER TO postgres;

--
-- Name: COLUMN active_account.email; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.active_account.email IS 'login address';


--
-- Name: account account_email_key; Type: CONSTRAINT; Schema: public; Owner: postgres
--

ALTER TABLE ONLY public.account
    ADD CONSTRAINT account_email_key UNIQUE (email);


--
-- Name: account account_pkey; Type: CONSTRAINT; Schema: public; Owner: postgres
--

ALTER TABLE ONLY public.account
    ADD CONSTRAINT account_pkey PRIMARY KEY (id);


--
-- Name: session session_pkey; Type: CONSTRAINT; Schema: public; Owner: postgres
--

ALTER TABLE ONLY public.session
    ADD CONSTRAINT session_pkey PRIMARY KEY (token);


--
-- Name: account_data_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX account_data_idx ON public.account USING gin (data);


--
-- Name: account_nick_idx; Type: INDEX; Schema: public; Owner: postgres
--

CREATE INDEX account_nick_idx ON public.account USING btree (nick);


--
-- Name: session session_account_id_fkey; Type: FK CONSTRAINT; Schema: public; Owner: postgres
--

ALTER TABLE ONLY public.session
    ADD CONSTRAINT session_account_id_fkey FOREIGN KEY (account_id) REFERENCES public.account(id) ON DELETE CASCADE;


--
-- PostgreSQL database dump complete
--
